import { styled, Text } from '@tamagui/web';

import type { BadgeContract } from './Badge.contract';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { WebSpanProps } from '../../types/WebAttributes';

export type BadgeProps = WebSpanProps<BadgeContract>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const badgeFrame = {
	flexBasis: 'auto',
	minWidth: 0,
	minHeight: 0,
	wordWrap: 'inherit',
	render: 'span',
	display: 'flex',
	flexDirection: 'row',
	flexShrink: 1,
	alignItems: 'normal',
	justifyContent: 'center',
	overflow: 'hidden',
	width: 'fit-content',
	paddingBlock: 2,
	paddingInline: '$space.x4',
	textAlign: 'center',
	whiteSpace: 'nowrap',
	textDecoration: 'none',
	textOverflow: 'ellipsis',
	wordBreak: 'keep-all',
	borderRadius: '$radius.full',
	fontSize: '0.625rem',
	lineHeight: '0.75rem',
	fontWeight: '700',
	letterSpacing: 0,
} as const;

const badgeLooks = {
	primary: {
		color: '$rcx-font-pure-white',
		backgroundColor: '$rcx-badge-background-level-2',
	},
	secondary: {
		color: '$rcx-font-pure-white',
		backgroundColor: '$rcx-badge-background-level-1',
	},
	warning: {
		color: '$rcx-font-pure-white',
		backgroundColor: '$rcx-badge-background-level-3',
	},
	danger: {
		color: '$rcx-font-pure-white',
		backgroundColor: '$rcx-badge-background-level-4',
	},
} as const;

const badgeSizing = {
	regular: {
		minWidth: '$size.x16',
		minHeight: '$size.x16',
	},
	small: {
		minWidth: '$size.x8',
		minHeight: '$size.x8',
	},
} as const;

// end of generated

const BadgeFrame = styled(Text, {
	...badgeFrame,
	variants: {
		look: badgeLooks,
		sizing: badgeSizing,
	},
});

/**
 * Communicates notification’s amount and types.
 */
function Badge(props: BadgeProps) {
	const { variant = 'secondary', small, className, children } = props;
	const modifiers = [variant, small && 'small']
		.filter(Boolean)
		.map((modifier) => `rcx-badge--${modifier}`)
		.join(' ');

	return (
		<BadgeFrame
			look={variant}
			sizing={small ? 'small' : 'regular'}
			className={prependClassName(className, `rcx-box rcx-box--full rcx-badge ${modifiers}`)}
			render={<span {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} role={props.role} />}
		>
			{children}
		</BadgeFrame>
	);
}

export default Badge;
